        part={'id':f'S01-{i+1:02}-{locale}','scene':i+1,'semanticID':key,'voice':voice,'locale':locale,'model':request['model'],'text':text,'delivery':delivery,'format':'Original PCM/WAV retained; actual service format verified at generation','captionText':'Not copied from pronunciation-marked script; derive clean captions and timing from actual recording.','sourceLesson':'lessons/FATE2-S01/lesson.public.json','visualID':visual_id}
        part['requestSHA256']=hashlib.sha256(json.dumps({k:part[k] for k in ['text','delivery','voice','locale','model','format']},ensure_ascii=False,sort_keys=True).encode()).hexdigest()
